import { useQuery } from '@tanstack/react-query';
import { getJson } from '../../api/http';

// The cross-feature summary the home dashboard shows. It shares the ['dashboard'] key; any feature
// that changes a client, project or invoice can invalidate it to keep the counts and total in step.
export type DashboardSummary = {
  clientsCount: number;
  projectsCount: number;
  outstandingTotal: number;
};

export const dashboardKey = ['dashboard'] as const;

export function useDashboard() {
  return useQuery({
    queryKey: dashboardKey,
    queryFn: () => getJson<DashboardSummary>('/api/dashboard'),
  });
}

import { Link } from '@tanstack/react-router';
import { AppNav } from '../../slots/defs/appNav';

// The dashboard's presence in the nav bar — its own file filling the shared nav region, so the shell
// is not touched to add it (CLAUDE.md rule 1).
export const contribution = AppNav.fill({
  order: 5,
  Component: () => (
    <Link to="/dashboard" data-testid="nav-dashboard">
      Dashboard
    </Link>
  ),
});

