1	package net.officefloor.hq.app;
2	
3	import java.util.List;
4	import java.util.Map;
5	import org.springframework.context.annotation.Profile;
6	import org.springframework.jdbc.core.JdbcTemplate;
7	import org.springframework.web.bind.annotation.PostMapping;
8	import org.springframework.web.bind.annotation.RequestBody;
9	import org.springframework.web.bind.annotation.RequestMapping;
10	import org.springframework.web.bind.annotation.RestController;
11	
12	/**
13	 * Per-spec data setup for the harness (DESIGN.md §9). Profile-guarded so it exists ONLY under the
14	 * harness launch (bin/start sets spring.profiles.active=harness) — never in a real deploy. This is
15	 * APP CODE and EVOLVES with the schema (NOT pinned); a change that breaks a prior spec's seed is a
16	 * seed-path regression. Tests call these to ARRANGE data; they ASSERT only through the UI.
17	 */
18	@Profile("harness")
19	@RestController
20	@RequestMapping("/__test__")
21	public class TestSupportController {
22	
23	    private final Audit audit;
24	    private final JdbcTemplate jdbc;
25	
26	    public TestSupportController(Audit audit, JdbcTemplate jdbc) {
27	        this.audit = audit;
28	        this.jdbc = jdbc;
29	    }
30	
31	    /** Truncate all domain tables and clear the audit file so each spec starts clean. */
32	    @PostMapping("/reset")
33	    public void reset() {
34	        audit.clear();
35	        // projects -> clients foreign key: H2 refuses TRUNCATE on a referenced table, so drop
36	        // referential integrity for the truncate and restore it immediately after.
37	        jdbc.execute("SET REFERENTIAL_INTEGRITY FALSE");
38	        jdbc.execute("TRUNCATE TABLE project_tags RESTART IDENTITY");
39	        jdbc.execute("TRUNCATE TABLE tags RESTART IDENTITY");
40	        jdbc.execute("TRUNCATE TABLE notes RESTART IDENTITY");
41	        jdbc.execute("TRUNCATE TABLE tasks RESTART IDENTITY");
42	        jdbc.execute("TRUNCATE TABLE payments RESTART IDENTITY");
43	        jdbc.execute("TRUNCATE TABLE invoice_line_items RESTART IDENTITY");
44	        jdbc.execute("TRUNCATE TABLE invoices RESTART IDENTITY");
45	        jdbc.execute("TRUNCATE TABLE contacts RESTART IDENTITY");
46	        jdbc.execute("TRUNCATE TABLE projects RESTART IDENTITY");
47	        jdbc.execute("TRUNCATE TABLE clients RESTART IDENTITY");
48	        jdbc.execute("SET REFERENTIAL_INTEGRITY TRUE");
49	    }
50	
51	    /** Insert the fixture a spec needs; the payload shape evolves with the schema. */
52	    @PostMapping("/seed")
53	    @SuppressWarnings("unchecked")
54	    public void seed(@RequestBody Map<String, Object> fixture) {
55	        List<Map<String, Object>> clients = (List<Map<String, Object>>) fixture.get("clients");
56	        if (clients != null) {
57	            for (Map<String, Object> client : clients) {
58	                // Explicit fixture id (JPA save() would ignore it on an IDENTITY column).
59	                jdbc.update("INSERT INTO clients (id, name, email) VALUES (?, ?, ?)",
60	                        ((Number) client.get("id")).longValue(), client.get("name"),
61	                        client.get("email"));
62	            }
63	        }
64	        List<Map<String, Object>> projects = (List<Map<String, Object>>) fixture.get("projects");
65	        if (projects != null) {
66	            for (Map<String, Object> project : projects) {
67	                // status is optional in a fixture; default to ACTIVE (matching Flyway V21) when absent.
68	                Object status = project.get("status");
69	                // archived is optional; default to false (matching Flyway V15) when absent.
70	                Object archived = project.get("archived");
71	                // budget is optional; a project without one has no budget set (NULL, Flyway V22).
72	                Object budget = project.get("budget");
73	                jdbc.update("INSERT INTO projects (id, name, client_id, status, archived, budget)"
74	                        + " VALUES (?, ?, ?, ?, ?, ?)",
75	                        ((Number) project.get("id")).longValue(), project.get("name"),
76	                        ((Number) project.get("clientId")).longValue(),
77	                        status != null ? status.toString() : "ACTIVE",
78	                        archived != null && Boolean.parseBoolean(archived.toString()),
79	                        budget != null ? new java.math.BigDecimal(budget.toString()) : null);
80	            }
81	        }
82	        List<Map<String, Object>> contacts = (List<Map<String, Object>>) fixture.get("contacts");
83	        if (contacts != null) {
84	            for (Map<String, Object> contact : contacts) {
85	                jdbc.update("INSERT INTO contacts (id, client_id, name, email, contact_role)"
86	                        + " VALUES (?, ?, ?, ?, ?)",
87	                        ((Number) contact.get("id")).longValue(),
88	                        ((Number) contact.get("clientId")).longValue(), contact.get("name"),
89	                        contact.get("email"), contact.get("role"));
90	            }
91	        }
92	        List<Map<String, Object>> tasks = (List<Map<String, Object>>) fixture.get("tasks");
93	        if (tasks != null) {
94	            for (Map<String, Object> task : tasks) {
95	                // done is optional in a fixture; default to false (OPEN) when absent.
96	                Object done = task.get("done");
97	                jdbc.update("INSERT INTO tasks (id, project_id, title, done) VALUES (?, ?, ?, ?)",
98	                        ((Number) task.get("id")).longValue(),
99	                        ((Number) task.get("projectId")).longValue(), task.get("title"),
100	                        done != null && Boolean.parseBoolean(done.toString()));
101	            }
102	        }
103	        List<Map<String, Object>> notes = (List<Map<String, Object>>) fixture.get("notes");
104	        if (notes != null) {
105	            long maxId = 0;
106	            for (Map<String, Object> note : notes) {
107	                long id = ((Number) note.get("id")).longValue();
108	                maxId = Math.max(maxId, id);
109	                // `at` is an ISO instant (e.g. "2026-01-05T09:00:00Z"); store it as a UTC
110	                // timestamp so notes sort newest-first by the instant they were written.
111	                jdbc.update("INSERT INTO notes (id, target_type, target_id, note_text, at)"
112	                        + " VALUES (?, ?, ?, ?, ?)",
113	                        id, note.get("targetType"),
114	                        ((Number) note.get("targetId")).longValue(), note.get("text"),
115	                        java.time.OffsetDateTime.ofInstant(
116	                                java.time.Instant.parse(note.get("at").toString()),
117	                                java.time.ZoneOffset.UTC));
118	            }
119	            // Explicit-id inserts don't advance H2's IDENTITY counter, so a later JPA save() would
120	            // regenerate a seeded id and collide. Restart the counter past the seeded ids.
121	            if (maxId > 0) {
122	                jdbc.execute("ALTER TABLE notes ALTER COLUMN id RESTART WITH " + (maxId + 1));
123	            }
124	        }
125	        List<Map<String, Object>> tags = (List<Map<String, Object>>) fixture.get("tags");
126	        if (tags != null) {
127	            for (Map<String, Object> tag : tags) {
128	                // Explicit fixture id (JPA save() would ignore it on an IDENTITY column).
129	                jdbc.update("INSERT INTO tags (id, name) VALUES (?, ?)",
130	                        ((Number) tag.get("id")).longValue(), tag.get("name"));
131	            }
132	        }
133	        List<Map<String, Object>> projectTags =
134	                (List<Map<String, Object>>) fixture.get("projectTags");
135	        if (projectTags != null) {
136	            for (Map<String, Object> link : projectTags) {
137	                // The join row's own id is IDENTITY-generated; the fixture names only the pair.
138	                jdbc.update("INSERT INTO project_tags (project_id, tag_id) VALUES (?, ?)",
139	                        ((Number) link.get("projectId")).longValue(),
140	                        ((Number) link.get("tagId")).longValue());
141	            }
142	        }
143	        List<Map<String, Object>> invoices = (List<Map<String, Object>>) fixture.get("invoices");
144	        if (invoices != null) {
145	            for (Map<String, Object> invoice : invoices) {
146	                // status is optional in a fixture; default to UNPAID (matching Flyway V5) when absent.
147	                Object status = invoice.get("status");
148	                // issuedDate/dueDate are optional; fall back to the Flyway V7 column defaults when absent.
149	                Object issuedDate = invoice.get("issuedDate");
150	                Object dueDate = invoice.get("dueDate");
151	                // An invoice is built from line items (Flyway V13). Its amount is the worked-out sum
152	                // of qty * unitPrice across them (zero when there are none yet) — a fixture no longer
153	                // types a figure, it lists what is charged. (An explicit `amount` still wins if a
154	                // fixture gives one, for back-compatibility with lump-sum invoices.)
155	                List<Map<String, Object>> lineItems =
156	                        (List<Map<String, Object>>) invoice.get("lineItems");
157	                java.math.BigDecimal amount = java.math.BigDecimal.ZERO;
158	                if (lineItems != null) {
159	                    for (Map<String, Object> line : lineItems) {
160	                        java.math.BigDecimal unitPrice =
161	                                new java.math.BigDecimal(line.get("unitPrice").toString());
162	                        int qty = ((Number) line.get("qty")).intValue();
163	                        amount = amount.add(unitPrice.multiply(java.math.BigDecimal.valueOf(qty)));
164	                    }
165	                }
166	                if (invoice.get("amount") != null) {
167	                    amount = new java.math.BigDecimal(invoice.get("amount").toString());
168	                }
169	                long invoiceId = ((Number) invoice.get("id")).longValue();
